def score_memory(memory):
    score = 0.0

    if 'score' in memory:
        score = float(memory['score'])

    timestamp_str = memory['timestamp']
    # Handle both ISO format with and without timezone
    if timestamp_str.endswith('Z'):
        # UTC timezone
        timestamp = datetime.fromisoformat(timestamp_str.replace('Z', '+00:00'))
    else:
        # Try to parse as naive datetime
        try:
            timestamp = datetime.fromisoformat(timestamp_str)
        except ValueError:
            # If parsing fails, skip recency bonus
            timestamp = datetime.utcnow()

    # Compare in UTC (all naive datetimes are treated as UTC)
    current_time = datetime.utcnow()
    if (current_time - timestamp.replace(tzinfo=None) if timestamp.tzinfo else current_time - timestamp) < timedelta(hours=24):
        score += 0.2

    if memory.get('type') == 'user_interaction':
        score += 0.3
    elif memory.get('type') == 'important_decision':
        score += 0.5
    elif memory.get('type') == 'task_completion':
        score += 0.2

    tags = memory.get('tags', [])
    if len(tags) >= 3:
        score += 0.1
    elif len(tags) >= 5:
        score += 0.2

    reinforcements = memory.get('reinforced', 0)
    if reinforcements >= 2:
        score += 0.2 * min(reinforcements, 5)

    return min(score, 1.0)

